func TestSetLimitAcceptsValidUnicodeText(t *testing.T) {
	s, dir := open(t)
	mustPoint(t, s, "P1", "取水口")

	items := []string{"浊�度", "浊度", "ph\x00x", "pH", "PH"}
	for i, item := range items {
